// Generated by Oriel from the [Service] classes of Sample. Do not edit.
/* eslint-disable */

class CallErrorBase extends Error {
  /** The method that failed, as "Service.Method". */
  readonly method: string;
  /** The code of a [ServiceError] exception, or null. */
  readonly code: string | null;
  /** The public properties of a [ServiceError] exception, or null. */
  readonly data: unknown;

  constructor(method: string, message: string, code: string | null = null, data: unknown = null) {
    super(message);
    this.name = "CallError";
    this.method = method;
    this.code = code;
    this.data = code === null ? null : data;
  }
}

/**
 * The error a call rejects with: the C# method threw, or its arguments did not fit its parameters.
 * Errors of [ServiceError] exceptions have their code, which tells their data's type.
 */
export type CallError = CallErrorBase & ({ readonly code: "conflict"; readonly data: ConflictException } | { readonly code: null; readonly data: null });
export const CallError = CallErrorBase as unknown as {
  new (method: string, message: string, code?: string | null, data?: unknown): CallError;
  readonly prototype: CallError;
};

interface Bridge {
  call(method: string, args: unknown[]): Promise<unknown>;
  on(event: string, listener: (payload: unknown) => void): () => void;
  stream(method: string, args: unknown[]): AsyncIterable<unknown>;
}

function bridge(): Bridge {
  const runtime = (globalThis as { oriel?: Bridge }).oriel;
  if (!runtime) throw new Error("Oriel: window.oriel is missing; open this page in an Oriel window");
  return runtime;
}

async function call<T>(method: string, ...args: unknown[]): Promise<T> {
  // Arguments left out stay out, so that C# uses its defaults.
  while (args.length > 0 && args[args.length - 1] === undefined) args.pop();
  try {
    return (await bridge().call(method, args)) as T;
  } catch (err) {
    if (err instanceof Error && err.name === "CallError") {
      const { code, data } = err as { code?: string | null; data?: unknown };
      throw new CallError(method, err.message, code ?? null, data);
    }
    throw err;
  }
}

function stream<T>(method: string, ...args: unknown[]): AsyncIterable<T> {
  // Arguments left out stay out, so that C# uses its defaults.
  while (args.length > 0 && args[args.length - 1] === undefined) args.pop();
  return {
    [Symbol.asyncIterator](): AsyncIterator<T> {
      const items = bridge().stream(method, args)[Symbol.asyncIterator]();
      return {
        async next(): Promise<IteratorResult<T>> {
          try {
            return (await items.next()) as IteratorResult<T>;
          } catch (err) {
            if (err instanceof Error && err.name === "CallError") {
              const { code, data } = err as { code?: string | null; data?: unknown };
              throw new CallError(method, err.message, code ?? null, data);
            }
            throw err;
          }
        },
        async return(): Promise<IteratorResult<T>> {
          return (await items.return!()) as IteratorResult<T>;
        },
      };
    },
  };
}

function on<T>(event: string, listener: (payload: T) => void): () => void {
  return bridge().on(event, listener as (payload: unknown) => void);
}

// ---- Types ----

/** The deck changed on disk since it was opened. */
export interface ConflictException {
  readonly path: string;
  readonly version: number;
}

/** A presentation. */
export interface Deck {
  /** The title, shown on the first slide. */
  title: string;
  slides: Slide[];
  meta: Record<string, string | null>;
  id: string;
  created: string;
  thumbnail: string;
  readonly slideCount: number;
}

/** One page of a Deck. */
export interface Slide {
  title: string;
  theme: Theme;
  rating: number | null;
}

/** How a slide looks. */
export type Theme = "light" | "dark" | "highContrast";

// ---- Services ----

/** Opens, saves and searches decks. */
export const Decks = {
  /**
   * Reads the deck at path.
   * @param path Where the deck is, absolute.
   * @returns The deck, or null when there is none.
   */
  open(path: string): Promise<Deck | null> {
    return call("Decks.Open", path);
  },
  /**
   * Writes deck.
   *
   * The file is replaced atomically.
   */
  save(path: string, deck: Deck): Promise<void> {
    return call("Decks.Save", path, deck);
  },
  search(query: string, limit?: number, theme?: Theme | null): Promise<(string | null)[]> {
    return call("Decks.Search", query, limit, theme);
  },
  raw(value: unknown): Promise<unknown> {
    return call("Decks.Raw", value);
  },
  /** The slides of the deck at path, as they are read. */
  slides(path: string): AsyncIterable<Slide> {
    return stream("Decks.Slides", path);
  },
  /**
   * Fires when a deck changed on disk.
   * Calls listener with each payload of Decks.Changed; returns a function that stops listening.
   */
  onChanged(listener: (payload: Deck) => void): () => void {
    return on<Deck>("Decks.Changed", listener);
  },
} as const;

export const Greeter = {
  /** Returns a greeting. */
  greet(name: string): Promise<string> {
    return call("Greeter.Greet", name);
  },
  delete(default_: string, new_: boolean): Promise<void> {
    return call("Greeter.Delete", default_, new_);
  },
} as const;

// ---- Window ----

/**
 * Fires when files are dropped on this window, with their full paths and where they were
 * dropped, in CSS pixels of the page; the page's own drop event has their File objects.
 * Returns a function that stops listening.
 */
export function onFilesDropped(listener: (drop: { paths: string[]; x: number; y: number }) => void): () => void {
  return bridge().on("oriel:filesDropped", listener as (payload: unknown) => void);
}
